import React, { useEffect, useState } from 'react';

export default function AdminThemeToggle({
    className = '',
}: {
    className?: string;
}) {
    const [theme, setTheme] = useState<'dark' | 'light'>('dark');
    const [mounted, setMounted] = useState(false);

    const applyTheme = (targetTheme: 'dark' | 'light') => {
        const isLight = targetTheme === 'light';
        document.documentElement.classList.toggle('light', isLight);
        document.documentElement.classList.toggle('dark', !isLight);
        document.body.classList.toggle('light', isLight);
        document.body.classList.toggle('dark', !isLight);
    };

    useEffect(() => {
        setMounted(true);
        const storedTheme =
            (localStorage.getItem('zy-theme') as 'dark' | 'light') || 'dark';
        setTheme(storedTheme);
        applyTheme(storedTheme);
    }, []);

    const toggleTheme = () => {
        const nextTheme = theme === 'dark' ? 'light' : 'dark';
        setTheme(nextTheme);
        applyTheme(nextTheme);
        localStorage.setItem('zy-theme', nextTheme);
    };

    return (
        <button
            type="button"
            onClick={toggleTheme}
            aria-label="Toggle theme"
            title={`Switch to ${theme === 'dark' ? 'Light' : 'Dark'} Mode`}
            className={`flex cursor-pointer items-center justify-center rounded-xl transition-all duration-200 active:scale-95 ${className}`}
            style={{
                width: 38,
                height: 38,
                backgroundColor: 'var(--admin-button-secondary-bg)',
                border: '1px solid var(--admin-border)',
                color: 'var(--admin-text-primary)',
            }}
        >
            {!mounted || theme === 'dark' ? (
                /* Sun Icon for switching to light mode */
                <svg
                    width="17"
                    height="17"
                    viewBox="0 0 24 24"
                    fill="none"
                    stroke="currentColor"
                    strokeWidth="2"
                    strokeLinecap="round"
                    strokeLinejoin="round"
                >
                    <circle cx="12" cy="12" r="5" />
                    <line x1="12" y1="1" x2="12" y2="3" />
                    <line x1="12" y1="21" x2="12" y2="23" />
                    <line x1="4.22" y1="4.22" x2="5.64" y2="5.64" />
                    <line x1="18.36" y1="18.36" x2="19.78" y2="19.78" />
                    <line x1="1" y1="12" x2="3" y2="12" />
                    <line x1="21" y1="12" x2="23" y2="12" />
                    <line x1="4.22" y1="19.78" x2="5.64" y2="18.36" />
                    <line x1="18.36" y1="5.64" x2="19.78" y2="4.22" />
                </svg>
            ) : (
                /* Moon Icon for switching to dark mode */
                <svg
                    width="17"
                    height="17"
                    viewBox="0 0 24 24"
                    fill="none"
                    stroke="currentColor"
                    strokeWidth="2"
                    strokeLinecap="round"
                    strokeLinejoin="round"
                >
                    <path d="M21 12.79A9 9 0 1111.21 3 7 7 0 0021 12.79z" />
                </svg>
            )}
        </button>
    );
}
